  const targets = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns', 'nectar-net', 'hong-fang-ends'];
  let target = null;

  // Find first hackable target with root access
  for (const srv of targets) {
    if (ns.hasRootAccess(srv)) {
      target = srv;
      break;
    }
  }

  if (!target) {
    ns.tprint('No hackable servers found');
    return;
  }

  ns.tprint(`Starting hack loop on ${target}`);
  let hackCount = 0;
  const startTime = Date.now();
