/** @param {NS} ns */
export async function main(ns) {
  const servers = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns', 'nectar-net', 'harakiri-sushi', 'otto-stands', 'neo-net', 'zer0', 'max-hardware'];

  let target = null;

  // Find easiest target with root access or attempt nuke
  for (const srv of servers) {
    if (ns.hasRootAccess(srv)) {
      target = srv;
      break;
    }
  }

  if (!target) {
    ns.tprint('No servers with root access found. Attempting to nuke n00dles...');
    ns.nuke('n00dles');
    target = 'n00dles';
  }

  ns.tprint(`Selected target: ${target}`);

  // Main hack cycle - runs for ~24 hours
  while (true) {
    const money = ns.getServerMoneyAvailable(target);
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const maxMoney = ns.getServerMaxMoney(target);

    ns.tprint(`Target: ${target} | Money: $${money} / $${maxMoney} | Sec: ${sec.toFixed(1)} / ${minSec.toFixed(1)}`);

    // If security is elevated, weaken first
    if (sec > minSec + 0.1) {
      ns.tprint(`Weakening (sec: ${sec.toFixed(1)})`);
      await ns.weaken(target);
      continue;
    }

    // If money is below 80% max, grow
    if (money < maxMoney * 0.8) {
      ns.tprint(`Growing (money: ${money})`);
      await ns.grow(target);
      continue;
    }

    // Otherwise hack
    ns.tprint(`Hacking (money: ${money})`);
    await ns.hack(target);
  }
}

